using namespace std;
static uint64_t nowms(){timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return (uint64_t)t.tv_sec*1000+t.tv_nsec/1000000;}
static string trim(string s){size_t a=s.find_first_not_of(" \t\r"),b=s.find_last_not_of(" \t\r"); return a==string::npos?string():s.substr(a,b-a+1);}
static bool num(const string&s,uint64_t&n){if(s.empty())return false;n=0;for(unsigned char c:s){if(c<'0'||c>'9'||n>(UINT64_MAX-(c-'0'))/10)return false;n=n*10+c-'0';}return n>0;}
static bool tok(unsigned char c){return (c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||(c&&strchr("!#$%&'*+-.^_`|~",c));}
static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned char c=s[i++];if(c<128)continue;int n;uint32_t v,min;if(c>=0xc2&&c<=0xdf){n=1;v=c&31;min=128;}else if(c>=0xe0&&c<=0xef){n=2;v=c&15;min=2048;}else if(c>=0xf0&&c<=0xf4){n=3;v=c&7;min=65536;}else return false;if(i+n>s.size())return false;while(n--){unsigned char d=s[i++];if((d&0xc0)!=0x80)return false;v=(v<<6)|(d&63);}if(v<min||v>0x10ffff||(v>=0xd800&&v<=0xdfff))return false;}return true;}
static int hex(unsigned char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
struct Conn {int fd=-1,file=-1; uint64_t id=0,deadline=0; string input,output; size_t sent=0; off_t left=0; bool writing=false;};
struct Timer {uint64_t when,id;int fd;bool operator<(const Timer&o)const{return when>o.when;}};
static int ep,rootfd; static uint64_t headerlim,headertime,writetime,maxconn,seq=0;static size_t active=0;static vector<Conn*> clients;static priority_queue<Timer> timers;
static void closeconn(Conn*c){epoll_ctl(ep,EPOLL_CTL_DEL,c->fd,nullptr);close(c->fd);if(c->file>=0)close(c->file);clients[c->fd]=nullptr;delete c;--active;}
static void deadline(Conn*c,uint64_t d){c->deadline=d;timers.push({d,c->id,c->fd});}
static const char* reason(int s){switch(s){case 200:return "OK";case 400:return "Bad Request";case 403:return "Forbidden";case 404:return "Not Found";case 405:return "Method Not Allowed";case 431:return "Request Header Fields Too Large";default:return "Internal Server Error";}}
static void response(Conn*c,int status,int file=-1,off_t len=0){c->writing=true;c->file=file;c->left=len;c->input.clear();c->output="HTTP/1.1 "+to_string(status)+" "+reason(status)+"\r\nContent-Length: "+to_string((long long)len)+"\r\nConnection: close\r\n";if(status==200)c->output+="Content-Type: application/octet-stream\r\n";if(status==405)c->output+="Allow: GET\r\n";c->output+="\r\n";c->sent=0;deadline(c,nowms()+writetime);}
static int pathfile(const string&target,int &file,off_t &len){if(target.empty()||target[0]!='/'||target.find('#')!=string::npos)return 400;for(unsigned char c:target)if(c<=32||c==127||c=='\\')return 400;size_t q=target.find('?');string raw=target.substr(0,q),p;p.reserve(raw.size());for(size_t i=0;i<raw.size();i++){unsigned char c=raw[i];if(c=='%'){if(i+2>=raw.size())return 400;int a=hex(raw[i+1]),b=hex(raw[i+2]);if(a<0||b<0)return 400;c=(a<<4)|b;i+=2;}if(c==0||c=='\\')return 400;p.push_back(c);}if(!utf8(p))return 400;vector<string> parts;size_t i=1;bool dirpath=p.back()=='/';while(i<=p.size()){size_t j=p.find('/',i);if(j==string::npos)j=p.size();string part=p.substr(i,j-i);if(part=="..")return 403;if(part=="."&&j==p.size())dirpath=true;if(!part.empty()&&part!=".")parts.push_back(part);if(j==p.size())break;i=j+1;}if(parts.empty())return 403;int dir=rootfd;bool own=false;for(size_t k=0;k<parts.size();k++){bool last=k+1==parts.size();int fd=openat(dir,parts[k].c_str(),last?(O_RDONLY|O_NONBLOCK|O_NOFOLLOW|O_CLOEXEC):(O_PATH|O_NOFOLLOW|O_CLOEXEC));if(fd<0){int err=errno;struct stat st;bool nonregular=fstatat(dir,parts[k].c_str(),&st,AT_SYMLINK_NOFOLLOW)==0&&!S_ISREG(st.st_mode);if(own)close(dir);if(nonregular||err==ELOOP||err==EACCES||err==EPERM)return 403;return 404;}if(own)close(dir);own=false;struct stat st;if(fstat(fd,&st)<0){close(fd);return 404;}if(S_ISLNK(st.st_mode)){close(fd);return 403;}if(last){if(!S_ISREG(st.st_mode)||dirpath){close(fd);return 403;}file=fd;len=st.st_size;return 200;}if(!S_ISDIR(st.st_mode)){close(fd);return 403;}dir=fd;own=true;}if(own)close(dir);return 404;}
static void parse(Conn*c,size_t end){string &s=c->input;size_t line=s.find("\r\n");if(line==string::npos){response(c,400);return;}string req=s.substr(0,line);size_t a=req.find(' '),b=a==string::npos?string::npos:req.find(' ',a+1);if(a==string::npos||a==0||b==string::npos||b==a+1||req.find(' ',b+1)!=string::npos){response(c,400);return;}string method=req.substr(0,a),target=req.substr(a+1,b-a-1),version=req.substr(b+1);for(unsigned char ch:method)if(!tok(ch)){response(c,400);return;}if(version!="HTTP/1.0"&&version!="HTTP/1.1"){response(c,400);return;}bool cl=false;size_t pos=line+2;while(pos<end-2){size_t e=s.find("\r\n",pos);if(e==string::npos||e>end){response(c,400);return;}if(e==pos)break;size_t colon=s.find(':',pos);if(colon==string::npos||colon>=e||colon==pos){response(c,400);return;}string name=s.substr(pos,colon-pos);for(char &ch:name){if(!tok((unsigned char)ch)){response(c,400);return;}if(ch>='A'&&ch<='Z')ch+=32;}for(size_t i=colon+1;i<e;i++){unsigned char ch=s[i];if((ch<32&&ch!='\t')||ch==127){response(c,400);return;}}string val=trim(s.substr(colon+1,e-colon-1));if(name=="transfer-encoding"){response(c,400);return;}if(name=="content-length"){if(cl||val.empty()){response(c,400);return;}cl=true;for(char ch:val)if(ch!='0'){response(c,400);return;}}pos=e+2;}int fd=-1;off_t len=0;int status=pathfile(target,fd,len);if(method!="GET"&&status!=400){if(fd>=0)close(fd);fd=-1;status=405;len=0;}response(c,status,fd,len);}
static bool output(Conn*c){while(c->sent<c->output.size()){ssize_t n=send(c->fd,c->output.data()+c->sent,c->output.size()-c->sent,MSG_NOSIGNAL|(c->left>0?MSG_MORE:0));if(n>0){c->sent+=n;continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return true;return false;}while(c->left>0){size_t nsend=(size_t)min<off_t>(c->left,1<<20);ssize_t n=sendfile(c->fd,c->file,nullptr,nsend);if(n>0){c->left-=n;continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return true;return false;}return false;}
static bool input(Conn*c){char buf[16384];for(;;){if(nowms()>=c->deadline)return false;ssize_t n=recv(c->fd,buf,sizeof(buf),0);if(n>0){c->input.append(buf,(size_t)n);size_t end=c->input.find("\r\n\r\n");size_t bound=end==string::npos?c->input.size():end+4;for(size_t i=0;i<bound;i++){unsigned char ch=c->input[i];if(ch==0||(ch=='\n'&&(i==0||c->input[i-1]!='\r'))||(ch=='\r'&&i+1<bound&&c->input[i+1]!='\n')){response(c,400);return true;}}if(end!=string::npos){if(end+4>headerlim)response(c,431);else parse(c,end+4);return true;}if(c->input.size()>headerlim){response(c,431);return true;}continue;}if(n==0)return false;if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK)return true;return false;}}
int main(int argc,char**argv){if(argc!=3||string(argv[1])!="--config")return 1;ifstream f(argv[2]);if(!f)return 1;unordered_map<string,string> cfg;string line;while(getline(f,line)){if(line.find('\0')!=string::npos||!utf8(line))return 1;line=trim(line);if(line.empty()||line[0]=='#')continue;size_t p=line.find('=');if(p==string::npos)return 1;string k=trim(line.substr(0,p)),v=trim(line.substr(p+1));if(k.empty()||v.empty()||cfg.count(k))return 1;cfg[k]=v;}const char*keys[]={"listen","root","max_connections","header_bytes","header_timeout_ms","idle_timeout_ms","write_timeout_ms","max_requests","pipeline_depth"};if(cfg.size()!=9)return 1;for(auto k:keys)if(!cfg.count(k))return 1;uint64_t dummy;if(!num(cfg["max_connections"],maxconn)||!num(cfg["header_bytes"],headerlim)||!num(cfg["header_timeout_ms"],headertime)||!num(cfg["write_timeout_ms"],writetime)||!num(cfg["idle_timeout_ms"],dummy)||!num(cfg["max_requests"],dummy)||!num(cfg["pipeline_depth"],dummy))return 1;if(headertime>UINT64_MAX/2||writetime>UINT64_MAX/2)return 1;string root=cfg["root"];if(root.empty()||root[0]!='/')return 1;rootfd=open(root.c_str(),O_PATH|O_DIRECTORY|O_CLOEXEC);if(rootfd<0)return 1;string listen=cfg["listen"];size_t colon=listen.find(':');if(colon==string::npos||listen.find(':',colon+1)!=string::npos)return 1;uint64_t port;if(!num(listen.substr(colon+1),port)||port>65535)return 1;sockaddr_in addr{};addr.sin_family=AF_INET;addr.sin_port=htons((uint16_t)port);if(inet_pton(AF_INET,listen.substr(0,colon).c_str(),&addr.sin_addr)!=1)return 1;signal(SIGPIPE,SIG_IGN);int listener=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(listener<0)return 1;int one=1;setsockopt(listener,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));if(bind(listener,(sockaddr*)&addr,sizeof(addr))||::listen(listener,8192))return 1;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return 1;epoll_event ev{};ev.events=EPOLLIN;ev.data.fd=listener;if(epoll_ctl(ep,EPOLL_CTL_ADD,listener,&ev))return 1;clients.resize(16384,nullptr);array<epoll_event,1024> events;for(;;){uint64_t now=nowms();while(!timers.empty()&&timers.top().when<=now){Timer t=timers.top();timers.pop();if(t.fd>=0&&(size_t)t.fd<clients.size()){Conn*c=clients[t.fd];if(c&&c->id==t.id&&c->deadline==t.when)closeconn(c);}}int timeout=-1;if(!timers.empty()){uint64_t delta=timers.top().when>now?timers.top().when-now:0;timeout=(int)min<uint64_t>(delta,INT_MAX);}int n=epoll_wait(ep,events.data(),events.size(),timeout);if(n<0){if(errno==EINTR)continue;return 1;}for(int i=0;i<n;i++){int fd=events[i].data.fd;if(fd==listener){for(int k=0;k<256;k++){int s=accept4(listener,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(s<0){if(errno==EINTR){--k;continue;}break;}if(active>=maxconn||(size_t)s>=clients.size()){close(s);continue;}Conn*c=new Conn;c->fd=s;c->id=++seq;clients[s]=c;active++;deadline(c,nowms()+headertime);epoll_event e{};e.events=EPOLLIN|EPOLLRDHUP;e.data.fd=s;if(epoll_ctl(ep,EPOLL_CTL_ADD,s,&e)<0)closeconn(c);}continue;}if(fd<0||(size_t)fd>=clients.size())continue;Conn*c=clients[fd];if(!c)continue;if(!c->writing){if(!input(c)){closeconn(c);continue;}if(c->writing){if(!output(c)){closeconn(c);continue;}epoll_event e{};e.events=EPOLLOUT|EPOLLRDHUP;e.data.fd=fd;epoll_ctl(ep,EPOLL_CTL_MOD,fd,&e);}}else if(!output(c)){closeconn(c);continue;}}}}
